<script lang="ts">
 import PageHeader from '$lib/components/PageHeader.svelte'; import { searchAll } from '$lib/api/search'; import type { SearchResult } from '$lib/api/types'; let query=$state('');let result=$state<SearchResult|null>(null),loading=$state(false),errorMessage=$state('');
 async function search(event:SubmitEvent){event.preventDefault();if(!query.trim()){result=null;return}loading=true;try{result=(await searchAll(query.trim())).data}catch(e){errorMessage=e instanceof Error?e.message:'搜索失败'}finally{loading=false}}
</script>
<PageHeader title="全局搜索" eyebrow="Search" description="搜索你有权限访问的项目和任务；超级管理员还可以搜索用户。" /><section class="workspace-card"><form onsubmit={search}><input bind:value={query} placeholder="输入项目 Key、名称、任务编号或标题" /><button class="primary-button" disabled={loading}>{loading?'搜索中…':'搜索'}</button></form></section>{#if errorMessage}<div class="workspace-card error-state">{errorMessage}</div>{/if}{#if result}<div class="results"><section class="workspace-card"><h2>项目 <span>{result.projects.length}</span></h2>{#each result.projects as item}<a href={`/projects/${item.project_key}`}><code>{item.project_key}</code><strong>{item.name}</strong></a>{:else}<p class="empty-inline">没有匹配项目。</p>{/each}</section><section class="workspace-card"><h2>任务 <span>{result.tasks.length}</span></h2>{#each result.tasks as item}<a href={`/tasks/${item.task_key}`}><code>{item.task_key}</code><strong>{item.title}</strong></a>{:else}<p class="empty-inline">没有匹配任务。</p>{/each}</section><section class="workspace-card"><h2>用户 <span>{result.users.length}</span></h2>{#each result.users as item}<div class="user-row"><strong>{item.display_name}</strong><span>{item.account}</span></div>{:else}<p class="empty-inline">没有匹配用户或当前账号不可搜索用户。</p>{/each}</section></div>{/if}
<style>form{display:flex;gap:10px}form input{flex:1}.results{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}.results h2{margin-top:0}.results h2 span{color:var(--color-text-muted);font-size:13px}.results a,.user-row{display:flex;gap:10px;align-items:center;padding:11px 0;border-top:1px solid var(--color-border)}.results a{flex-wrap:wrap}.results code{font-family:var(--font-mono);font-size:11px;color:var(--color-primary-strong)}.user-row{justify-content:space-between}.user-row span{color:var(--color-text-muted);font-size:13px}.error-state{color:var(--color-danger);margin-top:16px}@media(max-width:850px){.results{grid-template-columns:1fr}}@media(max-width:560px){form{display:grid}}</style>
